import { Log, useTranslation } from '@fanfanlo';
import { Button, Stack, Switch, Typography, Chip } from '@mui/material';
import { useEffect, useState } from 'react';
import { MobileAlbumSettingPanel } from './MobileAlbumSettingPanel';
import { autoWebViewJs } from '@droid/android';
import { PhotoLibrary } from '@mui/icons-material';

const fileLog = new Log(false, 'MobileAlbumPanel_file');

interface IMobileAlbumStatus {
  isRunning: boolean;
  port: number;
  token: string;
  serverUrl: string;
}

export function MobileAlbumPanel() {
  const uiLog = fileLog.sub(false, '  MobileAlbumPanel_ui');
  const { t } = useTranslation('homepage/components/mobile-album/content');

  // 控制开关状态
  const [isServiceEnabled, setIsServiceEnabled] = useState(false);
  // 控制设置弹窗的显示和隐藏
  const [isSettingPanelOpen, setIsSettingPanelOpen] = useState(false);
  const [serviceStatus, setServiceStatus] = useState<IMobileAlbumStatus>({
    isRunning: false,
    port: 8080,
    token: '',
    serverUrl: ''
  });

  function refreshServiceStatus() {
    uiLog.info('refreshServiceStatus_fn');
    const script = `
    var status = com.fanfanlo.lib.mediaservice.MediaService.getServiceStatus();
    status;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<string>(script);
    if (errMsg) {
      uiLog.error('getServiceStatus error:', errMsg);
      return;
    }
    uiLog.info('getServiceStatus result:', javaResultString);

    if (javaResultString) {
      try {
        const status = JSON.parse(javaResultString) as IMobileAlbumStatus;
        setServiceStatus(status);
        setIsServiceEnabled(status.isRunning);
      } catch (e) {
        uiLog.error('Parse service status error:', e);
      }
    }
  }

  useEffect(() => {
    uiLog.info('useEffect - component mounted');
    refreshServiceStatus();
  }, []);

  const handleSwitchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    uiLog.info('handleSwitchChange_fn, checked:', event.target.checked);
    const checked = event.target.checked;

    if (checked) {
      const script = `
        var result = com.fanfanlo.lib.mediaservice.MediaService.startService();
        result;`;
      const { javaResultString, errMsg } = autoWebViewJs.callScript<string>(script);
      if (errMsg) {
        uiLog.error('startService error:', errMsg);
        return;
      }
      const success = javaResultString === 'true';
      if (success) {
        refreshServiceStatus();
      }
    } else {
      const script = `
        com.fanfanlo.lib.mediaservice.MediaService.stopService();
        true;`;
      autoWebViewJs.callScript(script);
      setIsSettingPanelOpen(false);
      refreshServiceStatus();
    }

    setIsServiceEnabled(checked);
  };

  const handleOpenSettingPanel = () => {
    uiLog.info('handleOpenSettingPanel_fn');
    setIsSettingPanelOpen(true);
  };

  const handleCloseSettingPanel = () => {
    uiLog.info('handleCloseSettingPanel_fn');
    setIsSettingPanelOpen(false);
    // 设置关闭后刷新状态
    refreshServiceStatus();
  };

  const handleOpenAlbum = () => {
    uiLog.info('handleOpenAlbum_fn');
    if (serviceStatus.serverUrl && serviceStatus.token) {
      const albumUrl = `${serviceStatus.serverUrl}/mobile-album?token=${serviceStatus.token}`;
      window.open(albumUrl, '_blank');
    }
  };

  return (
    <Stack direction="row" spacing={2} alignItems="center" sx={{ width: '100%' }}>
      <Typography variant="h6" sx={{ flexShrink: 0 }}>
        {t('MobileAlbumPanel.title')}
      </Typography>

      <Switch
        checked={isServiceEnabled}
        onChange={handleSwitchChange}
        inputProps={{ 'aria-label': 'controlled' }}
      />

      <Chip
        label={serviceStatus.isRunning ? t('MobileAlbumPanel.running') : t('MobileAlbumPanel.stopped')}
        color={serviceStatus.isRunning ? 'success' : 'default'}
        size="small"
      />

      <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>
        {t('MobileAlbumPanel.port')}: {serviceStatus.port}
      </Typography>

      <Button variant="outlined" onClick={handleOpenSettingPanel}>
        {t('MobileAlbumPanel.settingsButtonLabel')}
      </Button>

      <Button
        variant="contained"
        startIcon={<PhotoLibrary />}
        onClick={handleOpenAlbum}
        disabled={!serviceStatus.isRunning}
        size="small"
      >
        {t('MobileAlbumPanel.openAlbum')}
      </Button>

      <MobileAlbumSettingPanel
        open={isSettingPanelOpen}
        onClose={handleCloseSettingPanel}
      />
    </Stack>
  );
}