import { autoJsStoreUtils, autoWebViewJs } from "@droid/android";
import { Log, useTranslation } from "@fanfanlo";
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Stack,
  Chip,
  Typography,
  Alert,
  Box,
  Divider
} from "@mui/material";
import { useEffect, useState } from "react";
import { Security, Refresh } from "@mui/icons-material";

const fileLog = new Log(false, "MobileAlbumSettingPanel_file");

interface IMobileAlbumSetting {
  port: number;
  token: string;
}

interface IPermissionStatus {
  contentResolver: boolean;
  requiredPermissions: string[];
}

interface IMobileAlbumSettingPanelProps {
  open: boolean;
  onClose: () => void;
}

export function MobileAlbumSettingPanel(props: IMobileAlbumSettingPanelProps) {
  const uiLog = fileLog.sub(false, "  MobileAlbumSettingPanel_ui");
  const { t } = useTranslation('homepage/components/mobile-album/content');
  const { open, onClose } = props;

  const [initialSetting, setInitialSetting] = useState<IMobileAlbumSetting>({ port: 8080, token: '' });
  const [portInput, setPortInput] = useState(String(initialSetting.port));
  const [tokenInput, setTokenInput] = useState(initialSetting.token);
  const [portError, setPortError] = useState('');
  const [permissionType, setPermissionType] = useState('contentresolver');
  const [permissionStatus, setPermissionStatus] = useState<IPermissionStatus>({
    contentResolver: false,
    requiredPermissions: []
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState<'success' | 'error' | 'info'>('info');

  function checkUpdateSetting() {
    uiLog.info('checkUpdateSetting_fn');
    if (portError) {
      uiLog.warn('Port has an error, skipping update.');
      return;
    }

    const currentSetting: IMobileAlbumSetting = {
      port: Number(portInput),
      token: tokenInput,
    };

    if (currentSetting.port === initialSetting.port && currentSetting.token === initialSetting.token) {
      uiLog.info('Settings have not changed, skipping update.');
      return;
    }

    const settingBase64 = autoJsStoreUtils.btoaUtf8(JSON.stringify(currentSetting));
    const script = `
    com.fanfanlo.lib.mediaservice.MediaService.updateSettingBase64('${settingBase64}');
    `;
    uiLog.info('Calling updateSettingBase64 with script:', script);
    const { errMsg } = autoWebViewJs.callScript(script);
    if (errMsg) {
      uiLog.error('updateSettingBase64 error:', errMsg);
      showMessage('设置更新失败: ' + errMsg, 'error');
    } else {
      showMessage('设置已更新', 'success');
    }
  }

  const loadServiceSetting = () => {
    uiLog.info('loadServiceSetting_fn');
    const script = `
    var s = com.fanfanlo.lib.mediaservice.MediaService.loadSettingBase64();
    s;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<string>(script);
    if (errMsg) {
      uiLog.error('loadSettingBase64 error:', errMsg);
      return;
    }
    const str = autoJsStoreUtils.atobUtf8(javaResultString || '');
    if (!str) {
      uiLog.error('atobUtf8 result empty, javaResultString=', javaResultString);
      return;
    }
    const storedSetting = JSON.parse(str || '{}') as IMobileAlbumSetting;

    setInitialSetting(storedSetting);
    setPortInput(String(storedSetting.port));
    setTokenInput(storedSetting.token);
    setPortError('');
  };

  const checkPermissions = () => {
    uiLog.info('checkPermissions_fn');
    const script = `
    var permissions = com.fanfanlo.lib.mediaservice.MediaService.checkPermissions();
    permissions;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<string>(script);

    if (errMsg) {
      uiLog.error('checkPermissions error:', errMsg);
      return;
    }

    if (javaResultString) {
      try {
        const permissions = JSON.parse(javaResultString) as IPermissionStatus;
        uiLog.info('checkPermissions result:', permissions);
        setPermissionStatus(permissions);
      } catch (e) {
        uiLog.error('Parse permissions error:', e);
      }
    }
  };

  const requestPermissions = () => {
    uiLog.info('requestPermissions_fn');
    setLoading(true);
    const script = `
    var permissions = com.fanfanlo.lib.mediaservice.MediaService.requestContentResolverPermission();
    permissions;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<string>(script);

    if (errMsg) {
      uiLog.error('requestPermissions error:', errMsg);
      showMessage('申请权限失败: ' + errMsg, 'error');
    } else {
      showMessage('请在系统对话框中授予权限', 'info');
      setTimeout(() => {
        checkPermissions();
      }, 2000);
    }
    setLoading(false);
  };

  const setPermissionTypeHandler = (type: string) => {
    uiLog.info('setPermissionType_fn:', type);
    const script = `
    var result = com.fanfanlo.lib.mediaservice.MediaService.setPermissionType("${type}");
    result;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<string>(script);

    if (errMsg) {
      uiLog.error('setPermissionType error:', errMsg);
      showMessage('设置权限模式失败: ' + errMsg, 'error');
      return;
    }

    const success = javaResultString === 'true';
    if (success) {
      setPermissionType(type);
      showMessage('权限模式已更新', 'success');
    } else {
      showMessage('设置权限模式失败', 'error');
    }
  };

  const showMessage = (msg: string, type: 'success' | 'error' | 'info') => {
    setMessage(msg);
    setMessageType(type);
    setTimeout(() => setMessage(''), 3000);
  };

  const validatePort = (port: string) => {
    const portNum = Number(port);
    if (isNaN(portNum) || portNum < 1 || portNum > 65535) {
      setPortError('端口必须是1-65535之间的数字');
    } else {
      setPortError('');
    }
  };

  useEffect(() => {
    uiLog.info('useEffect_fn, open changed:', open);
    if (open) {
      loadServiceSetting();
      checkPermissions();
    }
  }, [open]);

  const handlePortChange = (value: string) => {
    setPortInput(value);
    validatePort(value);
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>{t('MobileAlbumSettingPanel.title')}</DialogTitle>
      <DialogContent>
        {message && (
          <Alert severity={messageType} sx={{ mb: 2 }}>
            {message}
          </Alert>
        )}

        <Stack spacing={3} sx={{ mt: 1 }}>
          <Box>
            <Typography variant="subtitle1" gutterBottom>
              {t('MobileAlbumSettingPanel.serviceConfig')}
            </Typography>
            <Stack spacing={2}>
              <TextField
                label={t('MobileAlbumSettingPanel.port')}
                value={portInput}
                onChange={(e) => handlePortChange(e.target.value)}
                error={!!portError}
                helperText={portError}
                size="small"
                type="number"
              />
              <TextField
                label={t('MobileAlbumSettingPanel.token')}
                value={tokenInput}
                onChange={(e) => setTokenInput(e.target.value)}
                size="small"
                disabled
                helperText={t('MobileAlbumSettingPanel.tokenHelp')}
              />
            </Stack>
          </Box>

          <Divider />

          <Box>
            <Typography variant="subtitle1" gutterBottom>
              {t('MobileAlbumSettingPanel.permissionConfig')}
            </Typography>
            <Stack spacing={2}>
              <FormControl size="small">
                <InputLabel>{t('MobileAlbumSettingPanel.permissionType')}</InputLabel>
                <Select
                  value={permissionType}
                  onChange={(e) => setPermissionTypeHandler(e.target.value)}
                  disabled={loading}
                >
                  <MenuItem value="contentresolver">{t('MobileAlbumSettingPanel.contentResolver')}</MenuItem>
                  <MenuItem value="saf">{t('MobileAlbumSettingPanel.saf')}</MenuItem>
                </Select>
              </FormControl>

              <Box>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
                  <Typography variant="body2">
                    {t('MobileAlbumSettingPanel.permissionStatus')}:
                  </Typography>
                  <Chip
                    label={permissionStatus.contentResolver ? t('MobileAlbumSettingPanel.permissionGranted') : t('MobileAlbumSettingPanel.permissionDenied')}
                    color={permissionStatus.contentResolver ? 'success' : 'error'}
                    size="small"
                  />
                  <Button
                    size="small"
                    startIcon={<Refresh />}
                    onClick={checkPermissions}
                    disabled={loading}
                  >
                    {t('MobileAlbumSettingPanel.refresh')}
                  </Button>
                </Stack>

                <Button
                  variant="outlined"
                  size="small"
                  startIcon={<Security />}
                  onClick={requestPermissions}
                  disabled={loading || permissionStatus.contentResolver}
                >
                  {t('MobileAlbumSettingPanel.requestPermissions')}
                </Button>
              </Box>
            </Stack>
          </Box>
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>
          {t('MobileAlbumSettingPanel.cancel')}
        </Button>
        <Button
          onClick={checkUpdateSetting}
          variant="contained"
          disabled={!!portError}
        >
          {t('MobileAlbumSettingPanel.save')}
        </Button>
      </DialogActions>
    </Dialog>
  );
}